+const navToggle = document.querySelector(".nav-toggle");
+const siteNav = document.querySelector(".site-nav");
+const liveRegion = document.querySelector("[data-live-region]");
+const cartCount = document.querySelector("[data-cart-count]");
+const yearNode = document.querySelector("[data-current-year]");
+const filterButtons = Array.from(document.querySelectorAll(".filter-btn"));
+const productCards = Array.from(document.querySelectorAll(".product-card"));
+const addButtons = Array.from(document.querySelectorAll(".add-to-bag"));
+
+let cartItems = Number(cartCount?.textContent || 0);
+
+const updateCartLabel = () => {
+  const label = `Shopping bag, ${cartItems} item${cartItems === 1 ? "" : "s"}`;
+  cartCount.textContent = String(cartItems);
+  navToggle?.setAttribute("aria-label", label);
+  document.querySelector(".cart-button")?.setAttribute("aria-label", label);
+};
+
+const announce = (message) => {
+  if (liveRegion) {
+    liveRegion.textContent = message;
+  }
+};
+
+navToggle?.addEventListener("click", () => {
+  const expanded = navToggle.getAttribute("aria-expanded") === "true";
+  navToggle.setAttribute("aria-expanded", String(!expanded));
+  siteNav?.classList.toggle("is-open", !expanded);
+});
+
+siteNav?.addEventListener("click", (event) => {
+  if (event.target instanceof HTMLAnchorElement && window.matchMedia("(max-width: 720px)").matches) {
+    navToggle?.setAttribute("aria-expanded", "false");
+    siteNav.classList.remove("is-open");
+  }
+});
+
+filterButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    const filter = button.dataset.filter || "all";
+
+    filterButtons.forEach((current) => {
+      current.classList.toggle("is-active", current === button);
+    });
+
+    productCards.forEach((card) => {
+      const matches = filter === "all" || card.dataset.collection?.includes(filter);
+      card.classList.toggle("is-hidden", !matches);
+    });
+
+    announce(`${filter === "all" ? "Showing all featured products" : `Showing ${filter} featured products`}.`);
+  });
+});
+
+addButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    cartItems += 1;
+    updateCartLabel();
+    announce(`${button.dataset.product} added to your bag.`);
+  });
+});
+
